// The Solvers: only a Solver Bot's chooser offers them, in a section of their own; the
// new-Solver dialog gives a new Solver one of them.
export const SOLVER_SHAPES = ['puff', 'sprout', 'cap', 'bell', 'cloud', 'spike', 'floppy', 'antenna', 'cactus', 'bulb', 'chick', 'frog']
// The characters any Bot may pick, six to a row. Ordinary Bots keep their id-based
// character; only DSH identities default to the blue whale (DSH_LOOK).
export const PICKER_SHAPES = Object.keys(CHARACTERS).filter(id => !SOLVER_SHAPES.includes(id))
export const PICKER_COLUMNS = 6
export const DEFAULT_SHAPES = ['star', 'moon', 'gumdrop', 'peanut', 'bunny', 'kitty', 'acorn']
export const FALLBACK_SHAPE = 'gumdrop'
// The team's first Main Bot, and the plugin's own mark in the sidebar.
export const MAIN_LOOK = Object.freeze({ shape: 'octopus', color: 'deepseek' })
// Existing whale asset, used only for DSH identities without a custom look.
export const DSH_LOOK = Object.freeze({ shape: 'whale', color: 'blue' })
// Character colors in picker order. Black, the gradients, and the dull gray and brown
// are never defaults; the user must pick them.
export const CHARACTER_COLORS = ['black', 'brown', 'red', 'orange', 'yellow', 'green', 'cyan', 'blue', 'violet', 'magenta', 'gray', 'aurora']
export const DEFAULT_COLORS = CHARACTER_COLORS.filter(color => !['black', 'gray', 'brown'].includes(color) && !GRADIENTS[color])
export const isColor = color => isHex(color) || Object.hasOwn(INKS, color)

// The default look of a Genie comes from its id (FNV-1a, then mulberry32 for the
// color and murmur3's fmix32 for the shape), so it is the same on every device.
export function fnv1a(text) {
  let value = 2166136261
  for (let index = 0; index < text.length; index += 1) value = Math.imul(value ^ text.charCodeAt(index), 16777619)
  return value >>> 0
}
export function defaultColor(id) {
  const t = (fnv1a(id) + 1831565813) | 0
  let n = Math.imul(t ^ (t >>> 15), 1 | t)
  n = (n + Math.imul(n ^ (n >>> 7), 61 | n)) ^ n
  return DEFAULT_COLORS[Math.floor((((n ^ (n >>> 14)) >>> 0) / 4294967296) * DEFAULT_COLORS.length)]
}
export function defaultShape(id) {
  let value = fnv1a(id) | 0
  value = Math.imul(value ^ (value >>> 16), 73244475)
  value = Math.imul(value ^ (value >>> 13), 3266489909)
  return DEFAULT_SHAPES[((value ^ (value >>> 16)) >>> 0) % DEFAULT_SHAPES.length]
}

// Ordinary Bots (including Genie) retain the look their id gives them.
const keepsIdLook = bot => bot?.kind !== 'dsh'

// A stored color wins; then the DSH whale's blue, or the ordinary Bot's id. With no Bot
// it is a black gumdrop.
export const colorOf = bot => (isColor(bot?.color) ? bot.color : bot?.id ? (keepsIdLook(bot) ? defaultColor(String(bot.id)) : DSH_LOOK.color) : 'black')
export function lookOf(bot) {
  const avatar = bot?.avatar ?? {}
  return {
    // A stored shape wins; only a DSH identity defaults to the whale.
    shape: hasShape(avatar.shape) ? avatar.shape : bot?.id ? (keepsIdLook(bot) ? defaultShape(String(bot.id)) : DSH_LOOK.shape) : FALLBACK_SHAPE,
    image: avatar.image,
    // A pet (pets.js) the Bot wears; a photo wins.
    pet: avatar.image || typeof avatar.pet?.id !== 'string' ? undefined : avatar.pet,
    color: colorOf(bot),
  }
}

// Registered shapes join the characters: `body(paint)` returns SVG markup in a
// `size` box and `eyes` lists the two capsules.
export const SHAPES = {}
for (const [id, character] of Object.entries(CHARACTERS)) {
  const layers = [
    ...(character.paints ?? []).map(([d, fill, opacity]) => `<path d="${d}" fill="${fill}" fill-opacity="${opacity}"/>`),
    `<path d="${character.shade}" fill="#000" fill-opacity=".14"/>`,
    `<path d="${character.light}" fill="#fff" fill-opacity=".16"/>`,
  ].join('')
  SHAPES[id] = { label: character.label ?? id[0].toUpperCase() + id.slice(1), size: 100, path: character.body, layers, eyes: character.eyes }
}
export const hasShape = id => typeof id === 'string' && Object.hasOwn(SHAPES, id)
export const shapeId = id => (hasShape(id) ? id : FALLBACK_SHAPE)
export const shapeOf = id => SHAPES[shapeId(id)]
// `flat` draws the silhouette alone, for masks and selection rings.
export function bodyOf(def, paint, flat = false) {
  if (def.path) return `<g fill-rule="evenodd"><path d="${def.path}" fill="${paint}"/>${flat ? '' : def.layers}</g>`
  try { return def.body(paint) } catch { return '' }
}
// What the eyes look like: a dark pupil with a catchlight, drawn over the hole the mask cuts,
// with the same classes as the mask's eyes so every blink, glance and squint moves both.
const PUPIL = '#0a0f1f'
const pupilMarkup = ([cx, cy, w, h, tilt]) => `<g transform="translate(${cx} ${cy}) rotate(${tilt})"><g class="bt-eye"><rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${w / 2}" fill="${PUPIL}"/><circle cx="${w * 0.12}" cy="${-h * 0.24}" r="${w * 0.3}" fill="#fff"/><circle cx="${-w * 0.16}" cy="${h * 0.22}" r="${w * 0.12}" fill="#fff" fill-opacity=".7"/></g></g>`
// Cheeks, just under and outside each eye.
const blushMarkup = ([cx, cy, w, h, tilt]) => `<ellipse cx="${cx}" cy="${cy + h * 0.56}" rx="${w * 0.78}" ry="${w * 0.4}" transform="rotate(${tilt} ${cx} ${cy})" fill="#ff5fb8" fill-opacity=".42"/>`
const eyeMarkup = ([cx, cy, w, h, tilt]) => `<g transform="translate(${cx} ${cy}) rotate(${tilt})"><rect class="bt-eye" x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${w / 2}"/></g>`
// A closed, happy eye (an upturned arc) in the same spot, shown while the mark is petted.
const happyEyeMarkup = ([cx, cy, w, h, tilt]) => `<g transform="translate(${cx} ${cy}) rotate(${tilt})"><path class="bt-eye-happy" opacity="0" d="M${-w * 0.62} ${h * 0.14}Q0 ${-h * 0.42} ${w * 0.62} ${h * 0.14}" fill="none" stroke="#000" stroke-width="${w * 0.5}" stroke-linecap="round"/></g>`
// A mask covering three boxes, so a bob or squash never clips the body at the edge.
export const maskBox = size => `maskUnits="userSpaceOnUse" x="${-size}" y="${-size}" width="${size * 3}" height="${size * 3}"`
export const holes = (def, eyes) => `<rect x="${-def.size}" y="${-def.size}" width="${def.size * 3}" height="${def.size * 3}" fill="#fff"/>${eyes}`

// MASK_ID stands for each mark's own mask id: a duplicate id resolves to its first
// copy, which stops painting once that copy unmounts or sits in a hidden subtree.
export const MASK_ID = '%MASK%'
let markSerial = 0
export const nextMarkSerial = () => (markSerial += 1)
export const markupCache = new Map()
export function characterMarkup(shape, color) {
  const key = `${shape}|${color}`
  let markup = markupCache.get(key)
  if (markup === undefined) {
    const def = shapeOf(shape)
    // The eyes sit in the mask, untransformed by their placement, so CSS blinks and
    // glances never replace where they sit.
    const eyes = `<g class="bt-gaze"><g class="bt-eyes" fill="#000">${def.eyes.map(eyeMarkup).join('')}${def.eyes.map(happyEyeMarkup).join('')}</g></g>`
    // The body is lit from the top left: a gradient from a paler ink through the ink to a
    // deeper one (a gradient color keeps its own stops).
    const ink = inkFill(color)
    const stops = GRADIENTS[color] ?? [[0, `color-mix(in srgb, ${ink} 58%, #fff)`], [0.5, ink], [1, `color-mix(in srgb, ${ink} 72%, #000)`]]
    const box = def.size
    const gradient = `<linearGradient id="${MASK_ID}g" gradientUnits="userSpaceOnUse" x1="${box * 0.18}" y1="${box * 0.08}" x2="${box * 0.8}" y2="${box * 0.95}">${stops.map(([offset, value]) => `<stop offset="${offset}" style="stop-color:${value}"/>`).join('')}</linearGradient>`
    const face = `<g class="bt-gaze"><g class="bt-eyes">${def.eyes.map(pupilMarkup).join('')}${def.eyes.map(happyEyeMarkup).join('').replaceAll('stroke="#000"', `stroke="${PUPIL}"`)}</g></g>`
    const body = `<g mask="url(#${MASK_ID})">${bodyOf(def, `url(#${MASK_ID}g)`)}</g>${def.eyes.map(blushMarkup).join('')}${face}`
    markup = `<defs>${gradient}<mask id="${MASK_ID}" ${maskBox(def.size)}>${holes(def, eyes)}</mask></defs><g class="bt-b">${def.wrap ? `<g transform="${def.wrap}">${body}</g>` : body}</g>`
    markupCache.set(key, markup)
  }
  return markup
}
const svgUrl = (inner, size) => `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}">${inner}</svg>`)}")`
export const maskCache = new Map()
export function maskOf(shape) {
  let mask = maskCache.get(shape)
  if (mask === undefined) {
    const def = shapeOf(shape)
    const body = `<g mask="url(#e)">${bodyOf(def, '#000', true)}</g>`
    mask = svgUrl(`<mask id="e" ${maskBox(def.size)}>${holes(def, def.eyes.map(eyeMarkup).join('').replaceAll('class="bt-eye"', 'fill="#000"'))}</mask>${def.wrap ? `<g transform="${def.wrap}">${body}</g>` : body}`, def.size)
    maskCache.set(shape, mask)
  }
  return mask
}
export const DEFAULT_MASK = maskOf(FALLBACK_SHAPE)

// A character's parts as separate pictures, for baking it into a pet's atlas (pet-bake.js):
// the body without its eye holes, lit and blushing as a mark draws it, and the eyes in each
// expression a pet's rows need, all in the character's 100-unit box.
const svgDoc = (inner, size) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size * 4}" height="${size * 4}">${inner}</svg>`
const eyesAs = (def, draw) => def.eyes.map(([cx, cy, w, eyeHeight, tilt], index) => `<g transform="translate(${cx} ${cy}) rotate(${tilt})">${draw(w, eyeHeight, index)}</g>`).join('')
export function bakeMarkup(shape, color) {
  const def = shapeOf(shape)
  const box = def.size
  const ink = inkFill(color)
  const stops = GRADIENTS[color] ?? [[0, `color-mix(in srgb, ${ink} 58%, #fff)`], [0.5, ink], [1, `color-mix(in srgb, ${ink} 72%, #000)`]]
  const gradient = `<defs><linearGradient id="g" gradientUnits="userSpaceOnUse" x1="${box * 0.18}" y1="${box * 0.08}" x2="${box * 0.8}" y2="${box * 0.95}">${stops.map(([offset, value]) => `<stop offset="${offset}" style="stop-color:${value}"/>`).join('')}</linearGradient></defs>`
  const wrap = inner => (def.wrap ? `<g transform="${def.wrap}">${inner}</g>` : inner)
  const pupil = (w, eyeHeight, squint = 1, drop = 0) => `<g transform="translate(0 ${drop}) scale(1 ${squint})"><rect x="${-w / 2}" y="${-eyeHeight / 2}" width="${w}" height="${eyeHeight}" rx="${w / 2}" fill="${PUPIL}"/><circle cx="${w * 0.12}" cy="${-eyeHeight * 0.24}" r="${w * 0.3}" fill="#fff"/><circle cx="${-w * 0.16}" cy="${eyeHeight * 0.22}" r="${w * 0.12}" fill="#fff" fill-opacity=".7"/></g>`
  const arc = (w, eyeHeight, up) => `<path d="M${-w * 0.62} ${eyeHeight * (up ? 0.14 : -0.14)}Q0 ${eyeHeight * (up ? -0.42 : 0.42)} ${w * 0.62} ${eyeHeight * (up ? 0.14 : -0.14)}" fill="none" stroke="${PUPIL}" stroke-width="${w * 0.5}" stroke-linecap="round"/>`
  const faces = {
    open: eyesAs(def, (w, eyeHeight) => pupil(w, eyeHeight)),
    focused: eyesAs(def, (w, eyeHeight) => pupil(w, eyeHeight, 0.55)),
    closed: eyesAs(def, w => `<rect x="${-w * 0.62}" y="${-w * 0.22}" width="${w * 1.24}" height="${w * 0.44}" rx="${w * 0.22}" fill="${PUPIL}"/>`),
    happy: eyesAs(def, (w, eyeHeight) => arc(w, eyeHeight, true)),
    asleep: eyesAs(def, (w, eyeHeight) => arc(w, eyeHeight, false)),
    sad: eyesAs(def, (w, eyeHeight, index) => `${pupil(w, eyeHeight, 0.7, eyeHeight * 0.12)}${index === 0 ? `<path d="M0 ${eyeHeight * 0.55}q${w * 0.5} ${w * 0.9} 0 ${w * 1.3}q${-w * 0.5} ${-w * 0.4} 0 ${-w * 1.3}z" fill="#5bb7ff"/>` : ''}`),
  }
  return {
    box,
    body: svgDoc(`${gradient}${wrap(`${bodyOf(def, 'url(#g)')}${def.eyes.map(blushMarkup).join('')}`)}`, box),
    faces: Object.fromEntries(Object.entries(faces).map(([name, inner]) => [name, svgDoc(wrap(inner), box)])),
  }
}
